    #[test]
    fn test_render_appends_unambiguous_return_contract_section() {
        let contract = r#"{ "outcome": "string", "evidence": ["string"] }"#;
        let prompt = AgentIdentity::new("harw", "/ws")
            .with_return_contract(contract)
            .render_system_prompt();

        assert!(prompt.contains("## Return contract"));
        assert!(
            prompt.contains("exactly one JSON document"),
            "der Vertrag muss unmissverständlich formuliert sein"
        );
        assert!(
            prompt.contains("overrides every other instruction"),
            "der Vertrag muss Vorrang vor der Sprachregel beanspruchen"
        );
        assert!(prompt.ends_with(contract), "das Schema steht am Ende");
    }

    #[test]
    fn test_render_appends_mode_section_before_return_contract() -> TestResult {
        let prompt = AgentIdentity::new("harw", "/ws")
            .with_mode_section("Explore only.")
            .with_return_contract("{ \"finding\": \"string\" }")
            .render_system_prompt();

        let mode_at = prompt
            .find("## Interaction mode")
            .ok_or(TestError::Missing("mode section"))?;
        let contract_at = prompt
            .find("## Return contract")
            .ok_or(TestError::Missing("contract section"))?;
        assert!(
            mode_at < contract_at,
            "der Modus steht vor dem Rückgabevertrag"
        );
        Ok(())
    }

