    #[test]
    fn test_context_blocks_section_precedes_mode_and_return_contract() -> TestResult {
        let prompt = AgentIdentity::new("harw", "/ws")
            .with_trust_boundary_notice()
            .with_mode_section("Explore only.")
            .with_return_contract("{ \"finding\": \"string\" }")
            .render_system_prompt();

        let blocks_at = prompt
            .find("## Context blocks")
            .ok_or(TestError::Missing("context blocks section"))?;
        let mode_at = prompt
            .find("## Interaction mode")
            .ok_or(TestError::Missing("mode section"))?;
        let contract_at = prompt
            .find("## Return contract")
            .ok_or(TestError::Missing("contract section"))?;

        assert!(
            blocks_at < mode_at,
            "context blocks precede interaction mode"
        );
        assert!(
            mode_at < contract_at,
            "interaction mode precedes the return contract"
        );
        Ok(())
    }

    #[tokio::test]
    async fn test_provider_load_returns_system_prompt_and_fragments() {
        let identity = AgentIdentity::new("harw", "/workspace")
            .with_role("coding agent")
            .with_tools(vec!["fs.read".to_owned()])
            .with_extra_context(vec!["Extra note 1.".to_owned(), "Extra note 2.".to_owned()]);

        let provider = BaselineInstructionsProvider::new(identity);
        let loaded = provider.load().await;

        assert!(
            loaded.system_prompt.contains("harw"),
            "system_prompt must mention agent name"
        );
        assert!(
            loaded.system_prompt.contains("1. fs.read"),
            "system_prompt must list the tool"
        );
        assert_eq!(
            loaded.fragments,
            vec!["Extra note 1.", "Extra note 2."],
            "fragments must match extra_context"
        );
    }

    #[tokio::test]
    async fn test_provider_load_empty_fragments_when_no_extra_context() {
        let provider = BaselineInstructionsProvider::new(AgentIdentity::new("harw", "/workspace"));
        let loaded = provider.load().await;

        assert!(
            loaded.fragments.is_empty(),
            "fragments must be empty when no extra_context set"
        );
        assert!(
            !loaded.system_prompt.is_empty(),
            "system_prompt must still be non-empty"
        );
    }

    /// Belegt explizit, dass die Migration auf `#[instructions_provider]` das
    /// Verhalten nicht verändert hat: dieselbe `AgentIdentity` liefert exakt
    /// denselben `system_prompt` wie `render_system_prompt()` direkt, sowie
    /// die unveränderten `extra_context`-Fragmente.
    #[tokio::test]
    async fn test_provider_output_matches_pre_migration_shape() {
        let identity = AgentIdentity::new("harw", "/ws")
            .with_role("refactoring agent")
            .with_extra_context(vec!["note".to_owned()]);
        let expected_prompt = identity.clone().render_system_prompt();

        let provider = BaselineInstructionsProvider::new(identity);
        let loaded = provider.load().await;

        assert_eq!(loaded.system_prompt, expected_prompt);
        assert_eq!(loaded.fragments, vec!["note".to_owned()]);
    }
